import{_ as o,l as n,o as e,c as l,v as t,p as s,x as i,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"动态连通性","description":"","frontmatter":{"title":"动态连通性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dynamic-connectivity.md","filePath":"cs/dynamic-connectivity.md","lastUpdated":1789023840000}'),E={name:"cs/dynamic-connectivity.md"};function p(m,a,u,_,B,A){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="动态连通性" tabindex="-1">动态连通性 <a class="header-anchor" href="#动态连通性" aria-label="Permalink to &quot;动态连通性&quot;">​</a></h1><div class="epigraph"><p>边插入、删除时维护「是否同连通块」：插入用并查集；删除要树分解或 Euler Tour，均摊近对数。</p><footer>—— 据 Holm, de Lichtenberg and Thorup, Poly-Logarithmic Deterministic Fully-Dynamic Algorithms for Connectivity, 2001；并查集见 CLRS 第 21 章整理</footer></div><p>上一课<a href="/cs/contraction-hierarchies">收缩层次</a>预处理静态最短路。本课图在变：无向连通性的充分动态（插边+删边）。主干<a href="/cs/union-find">并查集</a>只合并、不拆。缺口是删边后如何重连。不重写路径压缩。后课流式模型：图自己也看不完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>半动态：只有插入（并查集），或只有删除（离线可重构）。充分动态：交错插删。离线删边：按时间倒过来变成插入。在线删边：维护生成森林；删树边后在「替换边」候选里找，或分层：每层生成森林，删边到下一层找替换（Holm 等）。均摊 \\(O(\\log^2 n)\\) 量级。</p><p>缺口是替换边，不是再 DFS 全图——那是 \\(O(n)\\) 每次。</p><h3 id="生成树不是-mst-动态" tabindex="-1">生成树不是 MST 动态 <a class="header-anchor" href="#生成树不是-mst-动态" aria-label="Permalink to &quot;生成树不是 MST 动态&quot;">​</a></h3><p>连通性不需要权。动态 MST 更难（权更新）。本课只 0-1 连通。2-边连通、动态平面性另论。</p><p><span class="marginnote">Holm–de Lichtenberg–Thorup 2001 确定性多对数。Euler Tour Tree 维护森林连通与子树。Sleator–Tarjan LCT 也可切边。后课图流：空间 \\(o(n)\\)，连森林都存不下。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入非树边：记为多余边。删非树边：直接丢。删树边：在覆盖该切分的非树边里找，或降层。查询 <code>find</code> 是否同一树根。</p>',11)),(e(),s(h,null,{default:i(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%8F%92%E8%BE%B9%22%5D%20--%3E%20UF%5B%22%E5%B9%B6%E5%85%A5%E6%A3%AE%E6%9E%97%20%2F%20%E8%AE%B0%E5%A4%9A%E4%BD%99%22%5D%0A%20%20DEL%5B%22%E5%88%A0%E8%BE%B9%22%5D%20--%3E%20REP%5B%22%E6%89%BE%E6%9B%BF%E6%8D%A2%E8%BE%B9%EF%BC%9F%22%5D%0A%20%20REP%20--%3E%20F%5B%22%E6%9B%B4%E6%96%B0%E7%94%9F%E6%88%90%E6%A3%AE%E6%9E%97%22%5D%0A%20%20F%20--%3E%20Q%5B%22%E5%90%8C%E5%9D%97%E6%9F%A5%E8%AF%A2%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>离线：时间倒流 + 并查集最简单。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>切分 \\((A,B)\\) 的替换边即跨 \\(A\\)、\\(B\\) 的剩余边。分层把边按「被当作树边的级别」限制扫描范围，均摊对数层。与点分治：这里动态，切的是边生命周期。不要用 CH 捷边当动态连通：对象是最短路不是 0-1。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写最优单元代价下界全文（有条件下界）。有向图动态强连通更难。后课默认：插边并查集；充分动态用分层森林或 LCT。下一课图流与半流：内存读一遍。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>插入易、删除要替换边或离线倒流。</li><li>充分动态可达多对数均摊。</li><li>只问连通，不是动态最短路。</li><li>出处：Holm, de Lichtenberg and Thorup, 2001；CLRS 并查集。</li></ul>',7))])}const b=o(E,[["render",p]]);export{f as __pageData,b as default};
